import numpy as np, mujoco, math
import driver
r = driver.build()
m, d = r.model, r.data
key = m.key('fixed_settled').id
def rp(r):
    _,R=r.get_base_pose()
    pitch=math.asin(max(-1,min(1,-R[2,0]))); roll=math.atan2(R[2,1],R[2,2])
    return roll,pitch
def settle(thigh, calf, steps=1500):
    mujoco.mj_resetDataKeyframe(m, d, key); mujoco.mj_forward(m, d)
    q = np.array([0,thigh,calf, 0,thigh,calf, 0,-thigh,-calf, 0,-thigh,-calf])
    hs=[]
    for k in range(steps):
        r.apply_pd_posture(q); r.step(1)
        if k>steps-300: hs.append(r.get_body_height())
    ro,pi=rp(r)
    v=r.get_base_velocity()["linear"]
    return dict(h=round(r.get_body_height(),4),hdrift=round(max(hs)-min(hs),4),
                roll=round(ro,4),pitch=round(pi,4),vspd=round(float(math.hypot(v[0],v[1])),4))
# find thigh for h in {0.30,0.35,0.40,0.44}
for th in (0.52,0.58,0.63,0.70):
    print("thigh",th, settle(th,-2*th))
